from pathlib import Path
import shutil
import json

ROOT = Path(__file__).resolve().parent

def icon(name):
    return f'<span class="icon" style="--icon:url(assets/icons/{name}.svg)" aria-hidden="true"></span>'

def photo(index, cls='', eager=False):
    names=['sapo-zinc','bibacter','povidone','permethrin','vitamin-b1']
    fa=['شامپو ساپو‌زینک ۲٪','ژل بی‌باکتر ۷۰٪','محلول پوویدون آیوداین ۱۰٪','شامپو پرمترین ۱٪','قرص ویتامین ب۱']
    return f'<img class="{cls}" src="assets/product-{names[index]}-cutout.webp" width="1536" height="1024" alt="عکس {fa[index]} از سایت ساپونین" '+('fetchpriority="high"' if eager else 'loading="lazy"')+'>'

